import fs from'node:fs';
import path from'node:path';

const root=path.resolve(import.meta.dirname,'..');
const ordered=['Config','SheetService','Auth','ReadmeService','GithubService','NotionService','PortfolioService','StudentService','ReadinessService','DashboardService','CheckService','ReportService','TriggerService','Code'];
const source=ordered.map(name=>{
  const filename=path.join(root,'apps-script',name+'.gs');
  return '// === '+name+'.gs ===\n'+fs.readFileSync(filename,'utf8').trim()+'\n';
}).join('\n');
const destination=path.join(root,'deployment','READY_Code.gs');
fs.mkdirSync(path.dirname(destination),{recursive:true});
fs.writeFileSync(destination,'// READY Apps Script bundle. Generated by tools/build-gas-bundle.mjs.\n// Replace the existing Code.gs content with this file, then save and deploy a new version.\n\n'+source,'utf8');
console.log(destination);
